"""Documentos y contactos desde el frontend sobre una persona DESARROLLO; sin limpieza masiva."""
import unittest,json,uuid,base64,urllib.request,urllib.parse,subprocess
from pathlib import Path
from playwright.sync_api import sync_playwright,expect
class DocumentosContactosClinica(unittest.TestCase):
 def test_documento_y_contacto(self):
  a=json.loads(Path('/Users/albertoalexanderitzepsarceno/Library/Application Support/GalenosSV/credentials.json').read_text())['administrador-local'];auth='Basic '+base64.b64encode((a['username']+':'+a['password']).encode()).decode()
  def get(path):
   with urllib.request.urlopen(urllib.request.Request('http://localhost:9080/GalenosSV/resources/v2/'+path,headers={'Authorization':auth}))as r:return json.load(r)
  person=next(p for p in get('persona?max=100') if p['nombres'].startswith('Desarrollo ') and p['apellidos']=='Prueba Desarrollo');token=uuid.uuid4().hex[:8]
  with sync_playwright()as p:
   b=p.chromium.launch(headless=True);page=b.new_page(viewport={'width':1440,'height':1100});errors=[];page.on('pageerror',lambda e:errors.append(str(e)));page.goto('http://localhost:3000');page.locator('[data-module=tipoDocumento]').click();page.locator('#gestion-usuario').fill(a['username']);page.locator('#gestion-clave').fill(a['password']);page.get_by_role('button',name='Iniciar sesión',exact=True).click();expect(page.locator('[data-catalogos] .gestion-tools').first).to_be_visible()
   for module,name in [('tipoDocumento','DESARROLLO documento '+token),('tipoMedioContacto','DESARROLLO contacto '+token)]:
    page.locator('[data-module='+module+']').click();page.get_by_role('button',name='Nuevo registro',exact=True).click();d=page.locator('#gestion dialog:visible');d.locator('[name=nombre]').fill(name);d.locator('[name=indicaciones]').fill('DESARROLLO para verificar persistencia');d.locator('[name=activo]').check();d.get_by_role('button',name='Guardar',exact=True).click();expect(d).not_to_be_visible()
   page.locator('[data-module=persona]').click();root=page.locator('[data-personas]');root.get_by_role('textbox',name='Filtrar nombres',exact=True).fill(person['nombres']);root.get_by_role('button',name='Buscar',exact=True).click();root.locator('tbody tr').filter(has_text=person['nombres']).get_by_role('button',name='Abrir',exact=True).click();expect(root.locator('.persona-relaciones')).to_contain_text(person['nombres']);root.get_by_role('button',name='Agregar documento',exact=True).click();d=root.locator('dialog');expect(d.locator('[name=idTipoDocumento] option').nth(1)).to_be_attached();d.locator('[name=idTipoDocumento]').select_option(label='DESARROLLO documento '+token);d.locator('[name=valor]').fill('DEV-'+token);d.get_by_role('button',name='Guardar',exact=True).click();expect(d).not_to_be_visible();line=root.locator('.persona-relaciones .gestion-tools').filter(has_text='DEV-'+token);line.dblclick();d.locator('[name=valor]').fill('DEV-'+token+'-EDIT');d.get_by_role('button',name='Guardar',exact=True).click();expect(d).not_to_be_visible();self.assertTrue(any(x['valor']=='DEV-'+token+'-EDIT' for x in get('documento?idPersona='+person['idPersona'])))
   page.once('dialog',lambda x:x.accept());line.get_by_role('button',name='Eliminar',exact=True).click();expect(line).to_have_count(0)
   root.get_by_role('button',name='Contactos',exact=True).click();root.get_by_role('button',name='Agregar medio de contacto',exact=True).click();expect(d.locator('[name=idTipoMedioContacto] option').nth(1)).to_be_attached();d.locator('[name=idTipoMedioContacto]').select_option(label='DESARROLLO contacto '+token);d.locator('[name=valor]').fill('dev-'+token+'@example.invalid');d.get_by_role('button',name='Guardar',exact=True).click();expect(d).not_to_be_visible();line=root.locator('.persona-relaciones .gestion-tools').filter(has_text='dev-'+token+'@example.invalid');line.dblclick();value='dev-'+token+'-edit@example.invalid';d.locator('[name=valor]').fill(value);d.get_by_role('button',name='Guardar',exact=True).click();expect(d).not_to_be_visible();self.assertTrue(any(x['valor']==value for x in get('medio_contacto?idPersona='+person['idPersona'])))
   uuid.UUID(person['idPersona']);sql="SELECT count(*) FROM medio_contacto WHERE id_persona='"+person['idPersona']+"' AND valor='"+value+"'";count=subprocess.check_output(['docker','exec','postgres_db','psql','-U','postgres','-d','clinica','-At','-c',sql],text=True).strip();self.assertEqual(count,'1');self.assertEqual(errors,[]);b.close()
if __name__=='__main__':unittest.main(verbosity=2)
